// JSON-Lines executed through the actual GutTS-compatible C++ API registry.
// Expected values are generated by pinned, compiled GutTS in CI.
#include "gut/api.hpp"
#include <iostream>
#include <stdexcept>
#include <string>
int main() {
  std::string line;
  while(std::getline(std::cin,line)) {
    try {
      const auto request=gut::parse_json(line);
      const auto& body=request.as<gut::json_value::object>();
      const auto& op=body.at("op").as<std::string>();
      gut::json_value::object input{{"value",body.at("value")}};
      if(op=="truncate") {
        input.emplace("maxLength",body.at("maxLength"));
        input.emplace("suffix",body.at("suffix"));
      }
      const auto result=gut::execute_gutts_api("gutts.strings."+op,input);
      if(!result||!std::holds_alternative<std::string>(result->data))
        throw std::logic_error("Unicode API result must be string");
      std::cout<<"{\"ok\":true,\"value\":"<<gut::stringify_json(*result)<<"}\n";
    }catch(const std::exception&) {
      std::cout<<"{\"ok\":false}\n";
    }
  }
  return std::cin.eof()&&std::cout.good()?0:1;
}
